function Set-TextReplace([string]$Path, [string]$Pattern, [string]$Replacement) {
  if (-not (Test-Path -LiteralPath $Path)) { throw "missing $Path" }
  $t = [IO.File]::ReadAllText($Path)
  $n = [regex]::Replace($t, $Pattern, $Replacement)
  if ($n -eq $t) { Write-Host "  WARN no change for /$Pattern/ in $Path" }
  else {
    [IO.File]::WriteAllText($Path, $n)
    Write-Host "  updated $Path"
  }
}

