function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $utf8 = New-Object System.Text.UTF8Encoding($false)
  [IO.File]::WriteAllText($Path, $Content, $utf8)
}

function Bump-GradleVersion([string]$BuildGradle) {
  $isKts = $BuildGradle.ToLower().EndsWith('.kts')
  $text = [IO.File]::ReadAllText($BuildGradle)
  if ($isKts) {
    $codeM = [regex]::Match($text, 'versionCode\s*=\s*(\d+)')
    $nameM = [regex]::Match($text, 'versionName\s*=\s*"([^"]+)"')
  } else {
    $codeM = [regex]::Match($text, 'versionCode\s+(\d+)')
    $nameM = [regex]::Match($text, 'versionName\s+"([^"]+)"')
  }
  if (-not $codeM.Success -or -not $nameM.Success) { throw "parse fail $BuildGradle" }
  $newCode = [int]$codeM.Groups[1].Value + 1
  $parts = @($nameM.Groups[1].Value -split '\.')
  while ($parts.Count -lt 3) { $parts += '0' }
  $newName = "$($parts[0]).$($parts[1]).$newCode"
  if ($isKts) {
    $text = [regex]::Replace($text, 'versionCode\s*=\s*\d+', "versionCode = $newCode")
    $text = [regex]::Replace($text, 'versionName\s*=\s*"[^"]+"', "versionName = `"$newName`"")
  } else {
    $text = [regex]::Replace($text, 'versionCode\s+\d+', "versionCode $newCode")
    $text = [regex]::Replace($text, 'versionName\s+"[^"]+"', "versionName `"$newName`"")
  }
  Write-Utf8NoBom $BuildGradle $text
  return $newName
}

function Build-One {
  param(
    [string]$Id,
    [string]$AppRoot,
    [string]$GradleDir,
    [string]$BuildGradle,
    [string]$DestDir,
    [string]$BaseName,
    [switch]$Native
  )
  $log = Join-Path $logDir "$Id.log"
  Write-Host "`n========== BUILD $Id ==========" -ForegroundColor Cyan
  try {
    $ver = Bump-GradleVersion $BuildGradle
    Write-Host "version -> $ver"
    Push-Location $GradleDir
    try {
      & .\gradlew.bat --stop 2>$null | Out-Null
      & .\gradlew.bat bundleRelease assembleRelease --stacktrace 2>&1 | Tee-Object -FilePath $log
      if ($LASTEXITCODE -ne 0) { throw "gradle failed exit=$LASTEXITCODE" }
    } finally { Pop-Location }

    $stage = 'D:\old\Mobile\scripts\stage-release-artifacts.ps1'
    if ($Native -and (Test-Path 'D:\.1 Work Stations\RootMC\Mobile App Files\rootmc-android\scripts\stage-release-artifacts.ps1') -and $Id -eq 'rootmc') {
      $stage = 'D:\.1 Work Stations\RootMC\Mobile App Files\rootmc-android\scripts\stage-release-artifacts.ps1'
    }
    New-Item -ItemType Directory -Force -Path $DestDir | Out-Null
    $stageArgs = @{
      AppDir = $AppRoot
      DestDir = $DestDir
      BaseName = $BaseName
      Version = $ver
    }
    if ($Native) { $stageArgs.Native = $true }
    & powershell -NoProfile -ExecutionPolicy Bypass -File $stage @stageArgs 2>&1 | Tee-Object -FilePath $log -Append
    if ($LASTEXITCODE -ne 0) { throw "stage failed exit=$LASTEXITCODE" }
    $line = "OK $Id v$ver -> $DestDir"
    Add-Content $summary $line
    Write-Host $line -ForegroundColor Green
  } catch {
    $line = "FAIL $Id : $($_.Exception.Message)"
    Add-Content $summary $line
    Write-Host $line -ForegroundColor Red
  }
}

