  }
  $aab = Get-ChildItem $aabDir -Filter '*.aab' -ErrorAction Stop | Where-Object { $_.Name -notmatch 'unsigned|debug' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  if (-not $aab) {
    $aab = Get-ChildItem $aabDir -Filter '*.aab' -ErrorAction Stop | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  }
  $apkSuffix = if ($apk.Name -match 'unsigned') { '-unsigned' } else { '' }
  $aabSuffix = if ($aab.Name -match 'unsigned') { '-unsigned' } else { '' }
  $apkDest = Join-Path $DestDir ("{0}-{1}{2}.apk" -f $BaseName, $Version, $apkSuffix)
  $aabDest = Join-Path $DestDir ("{0}-{1}{2}.aab" -f $BaseName, $Version, $aabSuffix)
